import cats.effect._
import cats.implicits._
import fs2.concurrent.SignallingRef
import grackle._
import grackle.QueryCompiler._
import grackle.syntax._

def mapping(ref: SignallingRef[IO, Int]): Mapping[IO] =
  new ValueMapping[IO] {
    val schema: Schema =
      schema"""
        type Query { get: Int! }
        type Mutation { put(n: Int): Int! }
      """

    val QueryType    = schema.ref("Query")
    val MutationType = schema.ref("Mutation")

    val typeMappings = List(
      ObjectMapping(QueryType, List(
        RootEffect.computeCursor("get")((path, env) =>
          ref.get.map(n => Result(valueCursor(path, env, n))))
      )),
      ObjectMapping(MutationType, List(
        RootEffect.computeCursor("put")((path, env) =>
          env.get[Int]("n") match {
            case None    => Result.failure(s"Implementation error: `n: Int` not found in $env").pure[IO]
            case Some(n) => ref.set(n).map(_ => Result(valueCursor(path, env, n)))
          })
      ))
    )

    override val selectElaborator: SelectElaborator =
      SelectElaborator {
        case (MutationType, "put", List(Query.Binding("n", Value.IntValue(n)))) =>
          Elab.env("n" -> n)
      }
  }

// run it:
for {
  ref <- SignallingRef[IO, Int](0)
  map  = mapping(ref)
  res <- map.compileAndRun("mutation { put(n: 42) }")
} yield res
// => { "data": { "put": 42 } }

// schema:  type Mutation { updatePopulation(id: Int!, population: Int!): City }
case class UpdatePopulation(id: Int, population: Int)

// effect supplied by the concrete (doobie) mapping:
def updatePopulation(id: Int, population: Int): IO[Unit] =
  sql"UPDATE city_copy SET population=$population WHERE id=$id"
    .update.run.transact(transactor).void

// field mapping on the Mutation object type:
RootEffect.computeUnit("updatePopulation")(env =>
  env.getR[UpdatePopulation]("updatePopulation").traverse {
    case UpdatePopulation(id, pop) => updatePopulation(id, pop)
  })

// elaborator: capture args AND rewrite the read-back query up front
case (MutationType, "updatePopulation",
      List(Binding("id", IntValue(id)), Binding("population", IntValue(pop)))) =>
  for {
    _ <- Elab.env("updatePopulation", UpdatePopulation(id, pop))
    _ <- Elab.transformChild(child =>
           Unique(Filter(Eql(CityType / "id", Const(id)), child)))
  } yield ()

// schema: type Mutation { createCity(name: String!, countryCode: String!, population: Int!): City }
case class CreateCity(name: String, countryCode: String, population: Int)

// effect: INSERT ... RETURNING id, supplied by the concrete (doobie) mapping
def createCity(name: String, countryCode: String, population: Int): IO[Int] =
  sql"""
    INSERT INTO city_copy (id, name, countrycode, district, population)
    VALUES (nextval('city_id'), $name, $countryCode, 'ignored', $population)
    RETURNING id
  """.query[Int].unique.transact(transactor)

// field mapping: rewrite the child query AFTER the insert, using the new id
RootEffect.computeChild("createCity")((child, _, env) =>
  env.getR[CreateCity]("createCity").flatTraverse {
    case CreateCity(name, cc, pop) =>
      createCity(name, cc, pop).map { id =>
        Unique(Filter(Eql(CityType / "id", Const(id)), child)).success
      }
  })

// elaborator only needs to capture the arguments (no transformChild here):
case (MutationType, "createCity",
      List(Binding("name", StringValue(name)),
           Binding("countryCode", StringValue(code)),
           Binding("population", IntValue(pop)))) =>
  Elab.env("createCity", CreateCity(name, code, pop))

val query = """
  mutation {
    createCity(name: "Wiggum", countryCode: "USA", population: 789) {
      name
      population
      country { name }
    }
  }
"""

val res = mapping.compileAndRun(query)   // IO[Json]

// expected:
// { "data": { "createCity": {
//     "name": "Wiggum", "population": 789,
//     "country": { "name": "United States" } } } }
